rules_version = '2';
service firebase.storage {
  match /b/{bucket}/o {
    function isAdmin() {
      return request.auth != null &&
        firestore.exists(/databases/(default)/documents/users/$(request.auth.uid)) &&
        firestore.get(/databases/(default)/documents/users/$(request.auth.uid)).data.role == 'admin';
    }

    function isServiceAccount() {
      return request.auth != null &&
        request.auth.token.firebase != null &&
        request.auth.token.firebase.sign_in_provider == 'service_account';
    }

    function isBackend() {
      // Backend calls must use a service account (authenticated), not unauthenticated requests
      return request.auth != null &&
        request.auth.token.firebase != null &&
        request.auth.token.firebase.sign_in_provider == 'service_account';
    }

    // Allow users to upload to temp_sources (e.g. Clip Studio uploads)
    match /temp_sources/{userId}/{allPaths=**} {
      allow read: if request.auth != null; // Authenticated users only
      allow write: if request.auth != null && request.auth.uid == userId
        && request.resource.size < 500 * 1024 * 1024; // 500MB limit
    }

    // Short-lived Find Viral Clips uploads. The backend verifies owner metadata,
    // creates a brief signed read URL for the worker, then deletes the source.
    match /temp_scans/{userId}/{allPaths=**} {
      allow read: if request.auth != null && request.auth.uid == userId;
      allow write: if request.auth != null && request.auth.uid == userId
        && request.resource.metadata.ownerUid == userId
        && request.resource.metadata.sourcePurpose == 'viral_scan'
        && request.resource.size < 500 * 1024 * 1024;
    }

    // Allow users to upload multicam sources for background sync / server render (large files, no hard cap)
    match /temp/multicam/{userId}/{allPaths=**} {
      allow read: if request.auth != null && request.auth.uid == userId;
      allow write: if request.auth != null && request.auth.uid == userId;
    }

    match /temp/multicam-clean-sync/{userId}/{allPaths=**} {
      allow read: if request.auth != null && request.auth.uid == userId;
      allow write: if request.auth != null && request.auth.uid == userId;
    }

    match /temp/multicam-clean-sync-audio/{userId}/{allPaths=**} {
      allow read: if request.auth != null && request.auth.uid == userId;
      allow write: if request.auth != null && request.auth.uid == userId;
    }

    // Original Cam Combiner media is uploaded once and automatically expires.
    // The explicit rule avoids the 50MB fallback cap while preserving ownership.
    match /temp/multicam-ingest/{userId}/{allPaths=**} {
      allow read: if request.auth != null && request.auth.uid == userId;
      allow write: if request.auth != null && request.auth.uid == userId;
    }

    // UnifiedPublisher uploads to uploads/<mediaType>s/... and the frontend enforces a 500MB cap.
    // Keep rules aligned so authenticated uploads do not fail with misleading permission errors.
    match /uploads/{allPaths=**} {
      allow read: if request.auth != null;
      allow write: if request.auth != null
        && request.resource.size < 500 * 1024 * 1024
        && (!firestore.exists(/databases/(default)/documents/users/$(request.auth.uid))
            || firestore.get(/databases/(default)/documents/users/$(request.auth.uid)).data.uploadBlocked != true);
    }

    // Allow all authenticated users to read and write files
    match /{allPaths=**} {
      allow read: if request.auth != null;
      allow write: if request.auth != null
        && request.resource.size < 50 * 1024 * 1024 // 50MB limit
        // PREVENT UPLOAD IF QUOTA EXCEEDED
        // Check if doc exists first to avoid error, then check property
        && (!firestore.exists(/databases/(default)/documents/users/$(request.auth.uid)) 
            || firestore.get(/databases/(default)/documents/users/$(request.auth.uid)).data.uploadBlocked != true);
    }

    // Allow public read access to published content
    match /content/{userId}/published/{allPaths=**} {
      allow read: if true;
      allow write: if (request.auth != null && request.auth.uid == userId) || isBackend()
        && request.resource.size < 50 * 1024 * 1024; // 50MB limit
    }

    // Allow users to read public assets
    match /public/{allPaths=**} {
      allow read: if true;
      allow write: if isAdmin() || isServiceAccount() || isBackend();
    }

    // Allow backend to write landing pages and public to read them
    match /landing-pages/{allPaths=**} {
      allow read: if true;
      allow write: if isBackend();
    }
  }
}
